// A · Mission Control (design @lisanogueira). Every number comes from web/data/ (LOLA + SPICE series,
// PGDA maps; PRELIMINARY → seal PRE), from GET /api/sites/{id}/sky (next_transitions; seal from its
// science_status) or from POST /api/onboard/site-evaluate with inputs the user declares (H1 is hypothetical → SIM).
// Missing value shows the dash glyph + N/D. Spec: designer/A-mission-control.designer.mds.
// Source of truth: this .tsx file (Preact). mission.js is generated by `npm --prefix web run build:ts`.
// The side panels are Preact templates rendered once into detached nodes (build/one) and swapped in with
// replaceChildren, exactly like the hand-built DOM they replace; the map rays stay imperative SVG.
import { h, Fragment, render } from "../../vendor/preact/preact.module.js";
import type { ComponentChild } from "../../vendor/preact/preact.module.js";
import { mountShell } from "../core/shell.js";
import { mountTerrain } from "../core/terrain.js";
import { loadSites, windowMetrics, dailySun, sealFor, apiOnline, api, loadRegion, sourced } from "../core/data.js";
import type { Site, SitesDoc, SiteSeriesLike, Sourced } from "../core/data.js";
import { createLayerCard, statCircle, barEl, sealEl } from "../core/layers.js";
import { t, fmtNum, lang } from "../core/i18n.js";
import { getState, setState, onState, hrefTo } from "../core/state.js";
import { runs, dayOf, fmtVal, mapDir, skyNext, batteryMargin, pgdaAt, compassIndex } from "./mission-calc.js";
import type { Runs, SkyPayload } from "./mission-calc.js";
import "./mission-i18n.js";

interface MissionSite extends Site { name: string; lon: number; stereo_x_m: number; stereo_y_m: number; site_height_m: number | null; source?: string; source_url?: string }
interface Doc extends Omit<SitesDoc, "sites"> { sites: MissionSite[] }
interface Geo { sunAz: number; sunEl: number; sunMargin: number; earthAz: number; earthEl: number; earthMargin: number }
interface Series extends SiteSeriesLike {
  at(t0: number): Geo | null;
  nextChange(t0: number, body: string): { status: string; hours: number; visible: boolean };
  meta: SiteSeriesLike["meta"] & { provenance?: { ephemeris?: string; terrain?: string } };
}
type Metrics = Omit<Awaited<ReturnType<typeof windowMetrics>>, "series"> & { series: Series };
interface Computed { m: Metrics; sunR: Runs | null; earthR: Runs | null; geo: Geo | null }
/** web/lab/terrain.js TerrainGrid, as far as this screen reads it (untyped JS module). */
interface Grid {
  h: { source: string; sha256: string; layers: Record<string, { file: string; product: string }> };
  normal(x: number, y: number): { slopeDeg: number };
}
interface Power { battery_capacity_wh: number; initial_charge_wh: number; reserve_wh: number; solar_generation_w: number; load_w: number }
interface EvalResult { ok: boolean; error?: string; data?: { combined_decision?: { status?: string } } }
interface EnergyOut { site: string; power: Power; res: EvalResult }
type Row = [string, string];

const H = 3600e3, DAY = 24;
const $ = (id: string) => document.getElementById(id) as HTMLElement;

/** Renders a template into detached DOM nodes. Preact is only a template engine here: nothing re-renders them. */
function build(v: ComponentChild): ChildNode[] {
  const c = document.createElement("div"); render(v, c); return [...c.childNodes];
}
const one = (v: ComponentChild): HTMLElement => build(v)[0] as HTMLElement;
/**
 * Embeds a DOM node built by the core (seals, bars, layer cards). The <mp-node> placeholder is swapped for the node
 * itself as soon as it is mounted, so the final DOM has no wrapper (child selectors in the CSS keep matching).
 */
function Node({ node }: { node: Node | null }) {
  return h("mp-node" as "span", { ref: (host: HTMLElement | null) => { if (host && node) host.replaceWith(node); } });
}

const nd = (): string => t("nd");
const unitTxt = (x: Sourced<number>, d = 0): string => x.value == null ? nd() : fmtNum(x.value, d) + (x.unit === "%" || x.unit === "°" ? x.unit : " " + x.unit);
const hrs = (v: number | null | undefined): string => fmtVal(v, fmtNum, nd(), 0, " h");
const deg = (v: number | null | undefined): string => fmtVal(v, fmtNum, nd(), 1, "°");

const shell = mountShell({ screen: "explore", context: null, onLang: () => draw() });
const doc = (await loadSites()) as unknown as Doc;
if (!doc.sites.some(s => s.id === getState().site)) setState({ site: doc.sites[0].id });
const hours = (): number => getState().hours || 14 * DAY;
const online = await apiOnline();
const grid = (await loadRegion()) as Grid & Record<string, any>; // TerrainGrid: untyped JS module
let pgda: { sun: Uint8Array | null; earth: Uint8Array | null } | null = null;
const pgdaP = Promise.all(["pgda_sun", "pgda_earth"].map(k => fetch(new URL("../../data/region/" + grid.h.layers[k].file, import.meta.url))
  .then(r => r.ok ? r.arrayBuffer() : null).then(b => b && new Uint8Array(b)))).then(([sun, earth]) => (pgda = { sun, earth })).catch(() => null);
const terrain = await mountTerrain($("terrain"), { sites: doc.sites, selected: getState().site, onSelect: (id: string) => setState({ site: id }) });
const site = (): MissionSite => doc.sites.find(s => s.id === getState().site) as MissionSite;
let tab = "overview", energyOut: EnergyOut | null = null, cur: Computed | null = null;

// Keep the chosen site in the free part of the map (between the side panels), not under them.
function frame() {
  const s = site(); terrain.select(s.id);
  // core/terrain.js already centres the site in the free area between the panels (an extra offset here moved it twice).
  terrain.redraw(); rays();
}

// Dotted Sun and Earth lines from the site along their local azimuth, labelled with the margin over the terrain horizon.
// Imperative on purpose: SVG geometry measured from the live layout on every frame/resize.
function rays() {
  const svg = $("rays"); svg.replaceChildren();
  // No projection yet (page opened hidden or at zero size): draw nothing rather than lines at "Infinity".
  if (!cur || !terrain.ready) { for (const id of ["ray-sun", "ray-earth"]) $(id).hidden = true; return; }
  const s = site(), W = innerWidth, Hh = innerHeight, [px, py] = terrain.toPx(s.stereo_x_m, s.stereo_y_m);
  svg.setAttribute("viewBox", `0 0 ${W} ${Hh}`);
  const g = cur.geo; if (!g) return;
  const len = Math.min(W, Hh) * (W > 700 ? .26 : .3);
  for (const [body, az, margin, color] of [["sun", g.sunAz, g.sunMargin, "#FFD166"], ["earth", g.earthAz, g.earthMargin, "#4C9BFF"]] as [string, number, number, string][]) {
    const [dx, dy] = mapDir(s.lon, az);
    // keep the Sun/Earth icon inside the free map area (below the context bar, above the dock)
    // Phone: the icon and its label (about 60 px) end above the sheet, never behind its glass.
    const pTop = matchMedia("(max-width:700px)").matches ? $("panels").getBoundingClientRect().top : Infinity;
    let L2 = len; const top = 150, bot = Math.min(Hh - 130, pTop - 64);
    if (dy < 0) L2 = Math.min(L2, (py - top) / -dy); if (dy > 0) L2 = Math.min(L2, (bot - py) / dy);
    L2 = Math.max(pTop < Infinity ? 40 : 60, L2);
    const x2 = px + dx * L2, y2 = py + dy * L2, x1 = px + dx * 30, y1 = py + dy * 30;
    const ln = document.createElementNS("http://www.w3.org/2000/svg", "line");
    Object.entries({ x1, y1, x2, y2, stroke: color, "stroke-width": 3, "stroke-dasharray": "2 8", "stroke-linecap": "round", opacity: margin >= 0 ? 1 : .45 }).forEach(([k, v]) => ln.setAttribute(k, String(v)));
    const dot = document.createElementNS("http://www.w3.org/2000/svg", "circle");
    Object.entries({ cx: x2, cy: y2, r: 16, fill: color }).forEach(([k, v]) => dot.setAttribute(k, String(v)));
    svg.append(ln, dot);
    const lab = $("ray-" + body); lab.hidden = false;
    lab.textContent = t((body === "sun" ? "mc.sun" : "mc.earth") + (margin >= 0 ? "Above" : "Below"), { n: deg(Math.abs(margin)) });
    lab.style.left = (x2 - dy * 0 + (dx >= 0 ? 0 : 0)) + "px"; { const ctxB = Math.max(...[".mp-top", ".mp-context", ].map(q => document.querySelector(q)?.getBoundingClientRect().bottom || 0)); // never under the context bar
      let ly = y2 + (dy > 0 ? 34 : -34); if (ly - 12 < ctxB + 8) ly = Math.max(y2 + 34, ctxB + 20); if (ly + 14 > pTop - 8) { ly = y2; lab.style.left = (x2 + (x2 < W / 2 ? 1 : -1) * (26 + lab.offsetWidth / 2)) + "px"; } lab.style.top = ly + "px"; }
  }
}

function satellites(r: Runs | null, labels: string[]) {
  const [a, b, c, d] = labels;
  return [{ value: r ? fmtNum(r.losses) : nd(), label: a }, { value: r ? hrs(r.longest) : nd(), label: b },
    { value: r && r.firstLoss != null ? t("mc.day", { n: dayOf(r.firstLoss) }) : nd(), label: c },
    { value: r && r.firstReturn != null ? t("mc.day", { n: dayOf(r.firstReturn) }) : nd(), label: d }];
}

async function compute(s: MissionSite): Promise<Computed> {
  const m = (await windowMetrics(doc, s, getState().start, hours())) as unknown as Metrics;
  const i0 = Math.ceil((m.t0 - m.series.start) / H);
  return { m, sunR: runs(m.series.sunMargin, i0, hours()), earthR: runs(m.series.earthMargin, i0, hours()), geo: m.series.at(m.t0) };
}

async function draw() {
  const st = getState(), s = site();
  cur = await compute(s);
  const { m, sunR, earthR } = cur;
  const fmtDate = (d: Date) => new Intl.DateTimeFormat(lang(), { dateStyle: "medium", timeStyle: "short", timeZone: "UTC" }).format(d) + " UTC";
  shell.setContext({ site: `${s.n} · ${s.name}`, date: fmtDate(new Date(m.t0)), days: fmtNum(hours() / DAY), seal: sealFor(doc.status), online,
    action: { label: t("ctx.compare"), href: hrefTo("compare.html") } });

  // ---- left column
  const tabs = (
    <div class="mc-tabs" role="tablist">{["overview", "notes"].map(k => (
      <button class="mp-pill" type="button" role="tab" aria-selected={tab === k} aria-pressed={tab === k} onClick={() => { tab = k; draw(); }}>{t("mc." + k)}</button>
    ))}</div>
  );
  let body: ComponentChild;
  if (tab === "notes") {
    body = (
      <div class="mp-card mc-notes">
        {([["mc.note.src", s.source], ["mc.note.cat", doc.note]] as [string, string | undefined][]).map(([k, v]) => <Fragment><h4 class="mp-label">{t(k)}</h4><p>{v || nd()}</p></Fragment>)}
        {s.source_url ? <a href={s.source_url} rel="noreferrer">{s.source_url}</a> : null}
      </div>
    );
  } else {
    const sunCircle = statCircle({ value: unitTxt(m.sunPct), label: t("mc.sunVisible"), seal: m.sunPct.seal, satellites: satellites(sunR, [t("mc.nights"), t("mc.longest"), t("mc.set"), t("mc.rise")]) });
    const ec = statCircle({ value: unitTxt(m.earthPct), label: t("mc.earth"), seal: m.earthPct.seal, satellites: satellites(earthR, [t("mc.losses"), t("mc.longest"), t("mc.loss"), t("mc.back")]) });
    ec.classList.add("mc-earth");
    const height = sourced(s.site_height_m, { unit: "m", status: doc.status, source: "web/data/sites.json · site_height_m" });
    const n = grid.normal(s.stereo_x_m, s.stereo_y_m);
    const slope = sourced(n.slopeDeg, { unit: "°", status: "ESTIMATE", source: "LOLA 400 m grid · central difference" });
    body = (
      <>
        <div class="mp-pill is-white mc-battery">{t("mc.battery")}</div>
        <div class="mc-circles"><Node node={sunCircle} /><Node node={ec} /></div>
        {([["mc.altitude", height], ["mc.slope", slope]] as [string, Sourced<number>][]).map(([k, v]) => (
          <div class="mp-pill is-white mc-metric"><span>{t(k)}</span><b class="mp-num">{unitTxt(v, v.unit === "°" ? 1 : 0)}</b><Node node={sealEl(v.seal)} /></div>
        ))}
        <Node node={energyCard(st, s, m)} /><Node node={contactCard(st, s, m)} /><Node node={terrainCard(st, s, height, slope)} />
      </>
    );
  }
  $("left").replaceChildren(...build(<>{tabs}{body}</>));

  // ---- right column
  const right = $("right"); right.replaceChildren(await numbersCard(s, m), await nowCard(s, m));
  // Earth compass: azimuth of the Earth at the window start, from the stored series (cur.geo); missing shows the dash glyph.
  const az = cur.geo?.earthAz as number, ci = compassIndex(az);
  right.append(...build(
    <div class="mc-compass" role="img" aria-label={`${t("mc.compass")} ${ci == null ? nd() : t("mc.dir." + ci)} ${fmtVal(az, fmtNum, nd(), 0, "°")}`}>
      <small>{t("mc.compass")}</small><b>{ci == null ? nd() : t("mc.dir." + ci)}</b><span class="mp-coord">{fmtVal(az, fmtNum, nd(), 0, "°")}</span>
    </div>));
  dock(s); frame();
}

function energyCard(st: ReturnType<typeof getState>, s: MissionSite, m: Metrics): HTMLElement {
  // Battery H1 is hypothetical: no default numbers. The user declares the inputs (kept in this page),
  // POST /api/onboard/site-evaluate runs the simulator; the screen shows only what the API returns.
  const night = m.longestDarkH.value;
  const out = energyOut && energyOut.site === s.id ? energyOut : null;
  const p = out?.power;
  const auton = p && p.load_w > 0 ? (p.initial_charge_wh - p.reserve_wh) / p.load_w : null;
  const margin = out?.res?.ok ? batteryMargin(auton as number, night as number) : null;
  const answer = margin == null ? t("mc.energy.ansNd", { n: hrs(night) }) : t("mc.energy.ans", { n: hrs(night), m: hrs(auton), k: hrs(margin) });
  const why = one(<div><Node node={barEl(dailySun(m.series, m.t0, hours()))} /><p class="mp-label">{t("mc.energy.why")}</p></div>);
  const fields: [keyof Power, string][] = [["battery_capacity_wh", "mc.energy.cap"], ["initial_charge_wh", "mc.energy.init"], ["reserve_wh", "mc.energy.res"], ["solar_generation_w", "mc.energy.gen"], ["load_w", "mc.energy.load"]];
  const onSubmit = async (e: Event) => {
    e.preventDefault(); const form = e.currentTarget as HTMLFormElement;
    const power = Object.fromEntries(fields.map(([k]) => [k, Number((form.elements.namedItem(k) as HTMLInputElement).value)])) as unknown as Power;
    const body = { mission_id: "moonproof-mission", start_utc: new Date(m.t0).toISOString().replace(".000Z", "Z"), duration_hours: Math.min(hours(), 720),
      candidates: [{ id: s.id, site_id: s.id, delay_hours: 0 }], power, max_comm_blackout_hours: getState().blackout };
    energyOut = { site: s.id, power, res: (await api<EvalResult["data"]>("/api/onboard/site-evaluate", { method: "POST", body })) as unknown as EvalResult }; draw();
  };
  const status = out ? (out.res.ok ? (out.res.data?.combined_decision?.status || nd()) : out.res.error) : nd();
  const rows: Row[] = [[t("mc.energy.auton"), hrs(margin == null ? null : auton)], [t("proof.source"), "POST /api/onboard/site-evaluate"], [t("proof.status"), status as string]];
  const proof = one(
    <div>
      <form class="mc-energy-form" onSubmit={onSubmit}>
        <p class="mp-label">{t("mc.energy.inputs")}</p>
        {fields.map(([k, lab]) => <label>{t(lab)}<input type="number" min="0" step="any" name={k} required value={p?.[k] ?? ""} /></label>)}
        <button class="mp-pill is-primary" type="submit">{t("mc.energy.run")}</button>
      </form>
      <table class="mp-proof"><tbody>{rows.map(([k, v]) => <tr><th>{k}</th><td>{v}</td></tr>)}</tbody></table>
    </div>);
  return createLayerCard({ id: "card-energy", title: t("mc.energy"), status: "SIMULATION", answer, why, proof, layer: st.layer, onLayer: (layer: string) => setState({ layer: layer as typeof st.layer }) }).el;
}

function contactCard(st: ReturnType<typeof getState>, _s: MissionSite, m: Metrics): HTMLElement {
  const why = one(<div><Node node={barEl(dailyEarth(m), "var(--earth)")} /><p class="mp-label">{t("mc.contact.why")}</p></div>);
  return createLayerCard({ id: "card-contact", title: t("mc.contact"), status: m.earthPct.status,
    answer: t("mc.contact.ans", { n: unitTxt(m.earthPct), m: unitTxt(m.longestBlackoutH) }), why, layer: st.layer, onLayer: (layer: string) => setState({ layer: layer as typeof st.layer }),
    proof: [[t("proof.definition"), t("mc.defEarth")], [t("proof.step"), m.earthPct.detail.step], [t("proof.window"), `${m.earthPct.detail.start} · ${fmtNum(hours())} h`],
      [t("proof.source"), `${m.series.meta.provenance?.ephemeris || ""} · ${m.series.meta.provenance?.terrain || ""}`], [t("proof.sha"), m.earthPct.detail.sha256],
      [t("proof.status"), `${m.earthPct.status} · ${t("seal." + m.earthPct.seal)}`]] }).el;
}
function dailyEarth(m: Metrics): (number | null)[] {
  const out: (number | null)[] = [], i0 = Math.ceil((m.t0 - m.series.start) / H);
  for (let d = 0; d * DAY < hours(); d++) { let on = 0, n = 0; for (let h = d * DAY; h < Math.min(hours(), d * DAY + DAY); h++) { const i = i0 + h; if (i < 0 || i >= m.series.count) continue; n++; if (m.series.earthMargin[i] >= 0) on++; } out.push(n ? on / n : null); }
  return out;
}

function terrainCard(st: ReturnType<typeof getState>, s: MissionSite, height: Sourced<number>, slope: Sourced<number>): HTMLElement {
  const ps = pgda ? pgdaAt(grid as never, pgda.sun, s.stereo_x_m, s.stereo_y_m) : null, pe = pgda ? pgdaAt(grid as never, pgda.earth, s.stereo_x_m, s.stereo_y_m) : null;
  const why = one(<p class="mp-label">{t("mc.terrain.why", { s: fmtVal(ps, fmtNum, nd(), 0, "%"), e: fmtVal(pe, fmtNum, nd(), 0, "%") })}</p>);
  // Two origins: height is PRE (LOLA), slope is EST (derived). The card shows the weaker one.
  return createLayerCard({ id: "card-terrain", title: t("mc.terrain"), status: slope.value == null ? height.status : slope.status,
    answer: t("mc.terrain.ans", { n: unitTxt(height), k: unitTxt(slope, 1) }), why, layer: st.layer, onLayer: (layer: string) => setState({ layer: layer as typeof st.layer }),
    proof: [[t("mc.altitude"), `${unitTxt(height)} · ${height.source} · ${height.seal}`], [t("mc.slope"), `${unitTxt(slope, 1)} · ${t("mc.defSlope")} · ${slope.seal}`],
      [t("proof.source"), `${grid.h.source} · sha256 ${grid.h.sha256}`], ["PGDA", `${grid.h.layers.pgda_sun.product} · ${grid.h.layers.pgda_earth.product}`]] }).el;
}

let otherId: string | null = null;
async function numbersCard(s: MissionSite, m: Metrics): Promise<HTMLElement> {
  const others = doc.sites.filter(x => x.id !== s.id);
  if (!others.some(x => x.id === otherId)) otherId = others[0].id;
  const o = others.find(x => x.id === otherId) as MissionSite, om = (await compute(o)).m;
  // Window length: the whole screen recomputes for it (state.hours). The current value is always an option.
  const winSel = (
    <select class="mc-win" aria-label={t("mc.window")} onChange={(e: Event) => setState({ hours: Number((e.currentTarget as HTMLSelectElement).value) })}>
      {[...new Set([7 * DAY, 14 * DAY, 28 * DAY, hours()])].sort((x, y) => x - y).map(hh => <option value={String(hh)} selected={hh === hours()}>{t("ctx.days", { n: fmtNum(hh / DAY) })}</option>)}
    </select>
  );
  const vsSel = (
    <select class="mc-vs" aria-label={`${t("mc.vs")} ${o.name}`} onChange={(e: Event) => { otherId = (e.currentTarget as HTMLSelectElement).value; draw(); }}>
      {others.map(x => <option value={x.id} selected={x.id === otherId} title={x.name}>{`${t("mc.vs")} ${x.n}`}</option>)}
    </select>
  );
  const hh = (x: Sourced<number>): number | null => x.value == null ? null : x.value * hours() / 100;
  const both = (w: Metrics): number | null => w.raw.status === "COMPUTED" ? (w.raw.bothPct as number) * hours() / 100 : null;
  const table = (title: string, rows: [string, number | null, number | null][], lowerBetter: boolean, withVs: boolean) => {
    const [a, b] = title.split(" · ");
    return (
      <>
        <div class="mc-num-sub"><h4 class="mp-label"><strong>{a}</strong>{b ? <span>{" · " + b}</span> : null}</h4>{withVs ? vsSel : null}</div>
        <table class="mc-table">
          <thead><tr><th></th><th>{`${s.n}`}</th><th>{`${o.n}`}</th></tr></thead>
          <tbody>{rows.map(([lab, x, y]) => {
            const differs = x != null && y != null && x !== y;
            const worseA = differs && (lowerBetter ? (x as number) > (y as number) : (x as number) < (y as number));
            return (
              <tr><th>{lab}</th>
                <td class={differs && worseA ? "is-worse" : undefined} title={differs && worseA ? t("mc.worse") : undefined}>{fmtVal(x, fmtNum, nd())}</td>
                <td class={differs && !worseA ? "is-worse" : undefined} title={differs && !worseA ? t("mc.worse") : undefined}>{fmtVal(y, fmtNum, nd())}</td></tr>
            );
          })}</tbody>
        </table>
      </>
    );
  };
  const prov = `${m.series.meta.provenance?.terrain || ""} · ${m.series.meta.provenance?.ephemeris || ""}`;
  return one(
    <article class="mp-card mc-numbers" id="card-numbers">
      <div class="mc-num-head"><h3>{t("mc.numbers", { site: `${t("ctx.site")} ${s.n}` })}</h3>{winSel}</div>
      {table(t("mc.windows"), [[t("mc.sunVisible"), hh(m.sunPct), hh(om.sunPct)], [t("mc.earth"), hh(m.earthPct), hh(om.earthPct)], [t("mc.sunAndEarth"), both(m), both(om)]], false, true)}
      {table(t("mc.risks"), [[t("mc.shadow"), m.longestDarkH.value, om.longestDarkH.value], [t("mc.loss.long"), m.longestBlackoutH.value, om.longestBlackoutH.value]], true, false)}
      <p class="mp-label mc-prov"><Node node={sealEl(m.sunPct.seal)} /><span title={prov}>{prov}</span></p>
    </article>);
}

async function nowCard(s: MissionSite, m: Metrics): Promise<HTMLElement> {
  const start = new Date(m.t0).toISOString().replace(".000Z", "Z");
  let r = skyNext(await api<SkyPayload | null>(`/api/sites/${encodeURIComponent(s.id)}/sky?start=${start}&hours=${Math.min(hours(), 720)}&step=3600`, { timeoutMs: 6000 }), "sun");
  let src = t("mc.now.src");
  if (r.hours == null && r.seal === "N/D" && !r.reason?.match(/no (change|transition)/i)) {
    // API off or site without API series: fall back to the stored hourly series (PRE), and say so.
    const nc = m.series.nextChange(m.t0, "sun");
    if (nc.status === "COMPUTED" && Number.isFinite(nc.hours)) r = { from: "api", seal: sealFor(doc.status), hours: nc.hours, kind: nc.visible ? "sunset" : "sunrise", reason: null };
    src = t("mc.now.local") + (r.reason ? "" : "");
  }
  // The data origin (API route or stored-series fallback) lives in the tooltip; the context bar already says offline.
  const icon = [0, 45, 90, 135, 180, 225, 270, 315].map(a => `<path d="M0 -7.5V-10.5" transform="rotate(${a})"/>`).join("");
  return one(
    <article class="mp-card mc-now" id="card-now" title={src}>
      <div class="mc-now-txt">
        <div class="mc-now-head"><h3 class="mp-label">{t("mc.now")}</h3><Node node={sealEl(r.seal)} /></div>
        <p class="mp-num mc-now-big">{r.hours == null ? nd() : `${fmtNum(Math.floor(r.hours))} h ${String(Math.round((r.hours % 1) * 60)).padStart(2, "0")}`}</p>
        <p class="mp-label mc-now-sub">{r.hours == null ? (r.reason || t("mc.now.none")) : t("mc.now." + r.kind)}</p>
      </div>
      <div class="mc-now-ico" aria-hidden="true">
        <svg viewBox="-12 -12 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" dangerouslySetInnerHTML={{ __html: '<circle r="4.2"/>' + icon }} />
      </div>
    </article>);
}

function dock(s: MissionSite) {
  const d = $("dock"), i = doc.sites.indexOf(s), n = doc.sites.length;
  const btn = (txt: string, label: string, fn: () => void, cls = "") => <button class={"mp-pill " + cls} type="button" aria-label={label} onClick={fn}>{txt}</button>;
  d.replaceChildren(...build(
    <>
      <p class="mc-hint">{t("mc.hint")}</p>
      <div class="mc-dock-row">
        {btn("‹", t("mc.prev"), () => setState({ site: doc.sites[(i + n - 1) % n].id }))}
        {btn("›", t("mc.next"), () => setState({ site: doc.sites[(i + 1) % n].id }))}
        <select class="mp-pill is-primary mc-sel" aria-label={t("ctx.site")}
          onChange={(e: Event) => setState({ site: (e.currentTarget as HTMLSelectElement).value })}
          onKeyDown={(e: KeyboardEvent) => { if (e.key === "ArrowLeft" || e.key === "ArrowRight") { e.preventDefault(); setState({ site: doc.sites[(i + (e.key === "ArrowLeft" ? n - 1 : 1)) % n].id }); } }}>
          {doc.sites.map(x => <option value={x.id} selected={x.id === s.id}>{`${t("ctx.site")} ${x.n} · ${x.name}`}</option>)}
        </select>
        {btn("−", t("mc.zout"), () => { terrain.zoom(0.7); frame(); })}
        {btn("+", t("mc.zin"), () => { terrain.zoom(1.4); frame(); })}
      </div>
    </>));
}

// Mobile sheet: drag the handle to resize.
const handle = $("handle"), panels = $("panels");
// Phone: the site/zoom dock lives inside the sheet, right under the handle, so it never covers the map
// (iPhone Safari 14/11: over the site label, and before that over the Earth marker). Desktop keeps it fixed at the bottom.
const phone = matchMedia("(max-width:700px)");
const placeDock = () => { const d = $("dock"); if (phone.matches) { if (d.parentElement !== panels) handle.after(d); } else if (d.parentElement !== document.body) document.body.append(d); };
phone.addEventListener?.("change", placeDock); placeDock();
handle.onpointerdown = e => { handle.setPointerCapture(e.pointerId); const y0 = e.clientY, h0 = panels.offsetHeight;
  handle.onpointermove = ev => { panels.style.height = Math.max(120, Math.min(innerHeight - 140, h0 + (y0 - ev.clientY))) + "px"; };
  handle.onpointerup = () => { handle.onpointermove = null; frame(); }; };
handle.onkeydown = e => { if (e.key === "ArrowUp" || e.key === "ArrowDown") { e.preventDefault(); panels.style.height = Math.max(120, Math.min(innerHeight - 140, panels.offsetHeight + (e.key === "ArrowUp" ? 60 : -60))) + "px"; frame(); } };

addEventListener("resize", () => frame());
let last = getState().site;
onState(s => { if (s.site !== last) { last = s.site; } draw(); });
pgdaP.then(() => draw());
draw();
